#!/usr/bin/env node
/**
 * Collapses byte-identical files across public/games into one shared master plus
 * symlinks.
 *
 * Why: several titles ship the same payload verbatim — one Ruffle runtime in 47
 * Flash games, the same nape.min.js in six, the same art atlases twice over.
 * Git stores those blobs once, but every checkout writes every copy to disk and
 * every deploy uploads every copy again, which was ~440 MB in a 3.2 GB tree.
 *
 * public/games/_shared is a hand-written directory (gg-save.js lives there), so
 * it is never scanned or cleared — only the generated bytes in SHARED are.
 *
 * Where the masters live matters. They are kept OUTSIDE public/, in
 * .game-assets-shared/. Vercel's build copies public/ and dereferences links as
 * it goes; a master inside public/ makes it try to copy a file into a
 * subdirectory of itself ("Cannot copy X to a subdirectory of itself") and the
 * deployment fails. Keeping masters outside the copied tree sidesteps that
 * entirely, and the build still dereferences each link into a real file. No game
 * is removed, shrunk, or altered — the bytes served are byte-identical.
 *
 *   node scripts/dedupe-game-assets.mjs            # report only
 *   node scripts/dedupe-game-assets.mjs --apply    # replace duplicates with links
 *   node scripts/dedupe-game-assets.mjs --restore  # turn links back into real files
 */
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const ROOT = path.resolve(import.meta.dirname, '..');
const GAMES = path.join(ROOT, 'public', 'games');
const SHARED = path.join(ROOT, '.game-assets-shared');
const MIN_BYTES = 64 * 1024; // below this the bookkeeping costs more than it saves
const APPLY = process.argv.includes('--apply');
const RESTORE = process.argv.includes('--restore');

/** Every regular file inside the game tree, following nothing. */
function walk(dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) walk(full, out);
    else if (entry.isFile()) out.push(full);
  }
  return out;
}

function sha256(file) {
  const hash = crypto.createHash('sha256');
  const fd = fs.openSync(file, 'r');
  const buf = Buffer.allocUnsafe(1 << 20);
  try {
    let read;
    while ((read = fs.readSync(fd, buf, 0, buf.length, null)) > 0) hash.update(buf.subarray(0, read));
  } finally {
    fs.closeSync(fd);
  }
  return hash.digest('hex');
}

function findLinks(dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) out.push(full);
    else if (entry.isDirectory()) findLinks(full, out);
  }
  return out;
}

if (RESTORE) {
  let restored = 0;
  for (const link of findLinks(GAMES)) {
    const target = path.resolve(path.dirname(link), fs.readlinkSync(link));
    if (!fs.existsSync(target)) {
      console.error('broken link, leaving alone:', path.relative(ROOT, link));
      continue;
    }
    const bytes = fs.readFileSync(target);
    fs.unlinkSync(link);
    fs.writeFileSync(link, bytes);
    restored++;
  }
  // The master store is only useful while links point at it. Never touch
  // public/games/_shared: that is hand-written code, not generated bytes.
  if (fs.existsSync(SHARED)) fs.rmSync(SHARED, { recursive: true, force: true });
  console.log(`Restored ${restored} link(s) into real files and removed the master store.`);
  process.exit(0);
}

const files = walk(GAMES).filter(file => {
  try { return fs.statSync(file).size >= MIN_BYTES; } catch { return false; }
});

const byHash = new Map();
for (const file of files) {
  const hash = sha256(file);
  (byHash.get(hash) || byHash.set(hash, []).get(hash)).push(file);
}

const dupes = [...byHash.entries()].filter(([, list]) => list.length > 1);
let reclaimable = 0;
for (const [, list] of dupes) reclaimable += fs.statSync(list[0]).size * (list.length - 1);

if (!APPLY) {
  console.log(`${files.length} files >= ${MIN_BYTES / 1024} KB scanned`);
  console.log(`${dupes.length} duplicated blobs, ${(reclaimable / 1048576).toFixed(0)} MB reclaimable`);
  for (const [, list] of dupes.sort((a, b) => fs.statSync(b[1][0]).size - fs.statSync(a[1][0]).size).slice(0, 12)) {
    console.log(`  ${(fs.statSync(list[0]).size / 1048576).toFixed(1)} MB x${list.length}  ${list.map(f => path.relative(GAMES, f)).join('  ')}`);
  }
  console.log('\nRe-run with --apply to replace the extra copies with links.');
  process.exit(0);
}

fs.mkdirSync(SHARED, { recursive: true });
let linked = 0;
let saved = 0;
for (const [hash, list] of dupes) {
  // Keep the first copy exactly where it is so at least one game owns real
  // bytes, then point every other copy at a master outside public/.
  const [keep, ...rest] = list;
  const master = path.join(SHARED, `${hash.slice(0, 16)}${path.extname(keep)}`);
  if (!fs.existsSync(master)) fs.copyFileSync(keep, master);
  const size = fs.statSync(keep).size;
  for (const file of rest) {
    fs.unlinkSync(file);
    // Relative, so the link resolves identically in this checkout and in
    // Vercel's /vercel/path0 clone. An absolute link would dangle in the build
    // container and turn the asset into a 404.
    fs.symlinkSync(path.relative(path.dirname(file), master), file);
    linked++;
    saved += size;
  }
}

console.log(`Linked ${linked} duplicate files, ${(saved / 1048576).toFixed(0)} MB no longer stored twice.`);
